const MVC_INFO={id:"maha-vir-chakra",name:"Maha Vir Chakra Explorer",fullTitle:"India's Second-Highest Wartime Gallantry Decoration",establishedDate:"26 January 1950 (Retroactive from 15 August 1947)",totalRecipients:218,posthumousCount:75,barToMvcRecipients:6,designer:"Armed Forces Honours Committee & India Government Mint",symbolism:"Five-pointed silver star bearing the gilded State Emblem of India (Ashoka Lions), symbolizing extraordinary wartime military valour",ribbonColor:"Half-white and half-orange silk ribbon (32 mm width)",quickStats:[{label:"Total Awardees",value:"218 Honorees",icon:"🎖️"},{label:"Wartime Valour Tier",value:"2nd Highest Wartime",icon:"⚔️"},{label:"Posthumous Awards",value:"75 Citations",icon:"🌹"},{label:"Bar to MVC (Twice)",value:"6 Heroes",icon:"⭐"},{label:"Wars Covered",value:"6 Major Operations",icon:"🇮🇳"},{label:"Medal Composition",value:"Standard Silver Star",icon:"🛡️"}]},MVC_HISTORY={overview:"The Maha Vir Chakra (MVC) is India's second-highest military decoration, awarded for acts of conspicuous gallantry in the presence of the enemy, whether on land, at sea, or in the air.",wartimeSignificance:"Instituted on Republic Day 1950, it recognizes acts of bravery performed during times of active military conflict against enemy forces. If a recipient performs another act of bravery matching the criteria, a Bar is awarded to be attached to the ribbon.",motto:"Conferred for exceptional gallantry, supreme tactical leadership, and courage under enemy fire."},MVC_ELIGIBILITY={title:"Eligibility Criteria",description:"The Maha Vir Chakra is open to all ranks of the Indian Armed Forces serving under operational wartime command.",categories:[{title:"Indian Army",detail:"Officers, JCOs, NCOs, and jawans across all arms including Infantry, Armoured Corps, Artillery, and Engineers."},{title:"Indian Navy",detail:"Naval officers and ratings serving aboard warships, submarines, or naval aviation squadrons during wartime combat."},{title:"Indian Air Force",detail:"Fighter pilots, bomber crews, and transport airmen flying operational combat missions over enemy airspace."},{title:"Reserve & Auxiliary Forces",detail:"Members of the Territorial Army and auxiliary forces called to active military duty."}]},MVC_MEDAL_DESIGN={shape:"Circular standard silver medal, 1.375 inches in diameter.",obverse:"Five-pointed heraldic star embossed on the disc, with a domed center featuring the gilt State Emblem of India (Ashoka Lion Capital).",reverse:"Embossed words 'MAHA VIR CHAKRA' in both Hindi ('महावीर चक्र') and English, separated by two lotus flowers.",ribbon:"Silk ribbon 32 mm wide, divided equally into half-orange and half-white vertical stripes."},MVC_OPERATIONS=[{title:"1947–48 Kashmir Operations",description:"Defending Jammu & Kashmir against tribal raiders and Pakistani regular troops, securing Uri, Poonch, and Zoji La Pass.",keyHero:"Brigadier Rajinder Singh & Major Chewang Rinchen"},{title:"1962 Sino-Indian War",description:"Fierce defense of Ladakh and NEFA frontiers against massive Chinese offensive waves under extreme weather.",keyHero:"Wing Commander Jag Mohan Nath & Major Dhan Singh Thapa"},{title:"1965 Indo-Pakistani War",description:"Large-scale tank battles at Phillora and Asal Uttar, and aerial dogfights over Sargodha and Chhamb-Jaurian.",keyHero:"Lt Col Desmond Hayde & Maj Gen Rajindar Singh"},{title:"1971 Bangladesh Liberation War",description:"Historic joint army, navy, and air force campaign leading to the liberation of Bangladesh and surrender of 93,000 enemy troops.",keyHero:"Lt Gen Jagjit Singh Aurora & Capt Mahendra Nath Mulla"},{title:"1999 Kargil War (Operation Vijay)",description:"Recapturing strategic high-altitude mountain peaks in Batalik, Dras, and Kargil sectors under intense enemy artillery fire.",keyHero:"Major Anuj Nayyar & Lt Col Gurpreet Singh"},{title:"2020 Galwan Valley Standoff",description:"Hand-to-hand combat defense at 15,000 feet in Ladakh against aggressive adversary troops at Patrol Point 14.",keyHero:"Colonel B. Santosh Babu"}],MVC_AWARDEES=[{id:"chewang-rinchen",name:"Major Chewang Rinchen",regiment:"Ladakh Scouts / 14 Jammu & Kashmir Militia",rank:"Major",year:1948,conflict:"1947 Kashmir War & 1971 Indo-Pak War (Bar to MVC)",posthumous:!1,citation:"Awarded MVC twice (Bar to MVC). At age 17 in 1948, he organized Nubra Guards and saved Leh. In 1971, captured Chalunka and Turtuk sector in Ladakh.",famousWords:"Youngest recipient of MVC at 17, and one of only six heroes awarded a Bar to Maha Vir Chakra.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Major_Chewang_Rinchen_MVC.jpg/800px-Major_Chewang_Rinchen_MVC.jpg"},{id:"rajinder-singh",name:"Brigadier Rajinder Singh",regiment:"Jammu and Kashmir State Forces",rank:"Brigadier",year:1947,conflict:"1947 Indo-Pakistani War",posthumous:!0,citation:"Known as the 'Savior of Kashmir'. Chief of Staff of J&K Forces who held Uri bridgehead with 150 men against thousands of raiders, buying time for Accession of J&K to India.",famousWords:"'Fight to the last man and last bullet to delay the enemy advance to Srinagar.'",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Brigadier_Rajinder_Singh_MVC.jpg/800px-Brigadier_Rajinder_Singh_MVC.jpg"},{id:"jag-mohan-nath",name:"Wing Commander Jag Mohan Nath",regiment:"No. 106 Reconnaissance Squadron, Indian Air Force",rank:"Wing Commander",year:1962,conflict:"1962 Sino-Indian War & 1965 Indo-Pak War (Bar to MVC)",posthumous:!1,citation:"Awarded MVC twice (Bar to MVC). Flew unescorted Canbbera reconnaissance missions deep into enemy territory over Aksai Chin (1962) and Pakistan (1965).",famousWords:"Legendary IAF reconnaissance pilot known as 'Jaggi', taking aerial photographs under heavy anti-aircraft fire.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Wg_Cdr_Jag_Mohan_Nath_MVC.jpg/800px-Wg_Cdr_Jag_Mohan_Nath_MVC.jpg"},{id:"anuj-nayyar",name:"Major Anuj Nayyar",regiment:"17th Battalion, Jat Regiment",rank:"Major",year:1999,conflict:"1999 Kargil War (Pimple II, Charlie Complex)",posthumous:!0,citation:"Led company assault on Pimple Complex on West Ridge in Kargil. Single-handedly destroyed three enemy bunkers and killed 9 enemy soldiers before a mortar shell struck him.",famousWords:"Secured strategic peak on Tiger Hill ridge line despite heavy enemy shell fire.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Major_Anuj_Nayyar_MVC.jpg/800px-Major_Anuj_Nayyar_MVC.jpg"},{id:"santosh-babu-mvc",name:"Colonel B. Santosh Babu",regiment:"16th Battalion, Bihar Regiment",rank:"Colonel",year:2021,conflict:"2020 Galwan Valley Standoff",posthumous:!0,citation:"Commanding Officer of 16 Bihar who displayed extraordinary courage, exemplary leadership, and conspicuous gallantry during physical conflict at Galwan River.",famousWords:"Led from the front in freezing Galwan waters to uphold Indian territorial integrity.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Col_Santosh_Babu.jpg/800px-Col_Santosh_Babu.jpg"},{id:"desmond-hayde",name:"Lieutenant Colonel Desmond Hayde",regiment:"3rd Battalion, Jat Regiment",rank:"Lieutenant Colonel",year:1965,conflict:"1965 Indo-Pakistani War (Battle of Dograi)",posthumous:!1,citation:"Commanded 3 Jat in the historic capture of Dograi town on the outskirts of Lahore, repulsing multiple armored counter-attacks.",famousWords:"'3 Jat will capture Dograi or die trying.' — Led his battalion to victory on the banks of Ichhogil Canal.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Lt_Col_Desmond_Hayde_MVC.jpg/800px-Lt_Col_Desmond_Hayde_MVC.jpg"}],MVC_TIMELINE=[{year:"1950",title:"Instituted on Republic Day",text:"Established by President Dr. Rajendra Prasad retroactive to 15 August 1947."},{year:"1947–1948",title:"Kashmir Operations",text:"First awards presented to heroes like Brig Rajinder Singh and Maj Chewang Rinchen."},{year:"1962",title:"Sino-Indian War",text:"Recognized high-altitude bravery in Ladakh and NEFA."},{year:"1965",title:"Indo-Pakistani War",text:"Decorated armored division commanders, infantry officers, and IAF pilots."},{year:"1971",title:"Bangladesh Liberation War",text:"Peak conferments recognizing historic tri-service victories."},{year:"1999",title:"Kargil War (Op Vijay)",text:"Honored heroes who recaptured mountain peaks overlooking National Highway 1D."},{year:"2020",title:"Galwan Valley Action",text:"Colonel B. Santosh Babu conferred MVC for supreme bravery in eastern Ladakh."}],MVC_FACTS=[{title:"Bar to Maha Vir Chakra",detail:"A total of six officers have been awarded the Bar to MVC for repeating acts of supreme wartime gallantry."},{title:"Youngest MVC Recipient",detail:"Chewang Rinchen received his first MVC at the age of 17 for defending the Nubra Valley in 1948."},{title:"Pure Silver Medal",detail:"The medal is cast in standard silver with a gilded state emblem, suspended on a half-white half-orange ribbon."},{title:"Precedence Order",detail:"Ranks second only to the Param Vir Chakra in wartime military decorations."},{title:"Tri-Service Recognition",detail:"Conferred on outstanding warriors across Army, Navy, Air Force, and local militia."},{title:"Posthumous Honor",detail:"Over 34% of all MVCs have been awarded posthumously to fallen heroes."}];"undefined"!=typeof module&&module.exports&&(module.exports={MVC_INFO:MVC_INFO,MVC_HISTORY:MVC_HISTORY,MVC_ELIGIBILITY:MVC_ELIGIBILITY,MVC_MEDAL_DESIGN:MVC_MEDAL_DESIGN,MVC_OPERATIONS:MVC_OPERATIONS,MVC_AWARDEES:MVC_AWARDEES,MVC_TIMELINE:MVC_TIMELINE,MVC_FACTS:MVC_FACTS});